(()=>{'use strict';const api=window.DesktopApp?.statistics;if(!api)return;const button=document.createElement('button'),status=document.createElement('span');button.type='button';button.className='button';button.textContent='Статистика игры';status.setAttribute('role','status');status.style.maxWidth='360px';(()=>{const group=document.createElement('div');group.style.cssText='display:flex;flex-direction:column;gap:4px;max-width:300px';status.style.cssText='font-size:12px;line-height:1.3;overflow-wrap:anywhere';group.append(button,status);document.querySelector('.header-actions')?.append(group)})();button.onclick=async()=>{button.disabled=true;status.textContent='Запуск статистики игры…';try{const state=await api.action('open');status.textContent=state.message;}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};api.onState(state=>{status.textContent=state.message;});})();
